/* Persist selectable times and program mappings together; Cancel never calls save. */
import org.json.JSONObject;
import org.json.JSONArray;
sleepValue(key) {
    value = tasker.getVariable(key);
    return value == null || value.startsWith("%") ? "" : value;
}
sleepPrograms() {
    names = new JSONArray();
    for (i = 1; i <= 6; i++) {
        name = sleepValue("SIG3_ProgramName" + i).trim();
        if (name.length() == 0) throw new Exception("Configure all six program names");
        for (j = 0; j < names.length(); j++)
            if (name.equals(names.getString(j))) throw new Exception("Program names must be unique");
        names.put(name);
    }
    return names;
}
sleepTimeValid(value) { return value.matches("(?:[01][0-9]|2[0-3])\\.[0-5][0-9]"); }
prefs = context.getSharedPreferences("heysig3-sleep", 0);
mode = sleepValue("sig3_sleep_pref_mode");
if ("save".equals(mode)) {
    sleepSlot = sleepValue("sig3_sleep_program_choice"); wakeSlot = sleepValue("sig3_wake_program_choice");
    sleepTime = sleepValue("sig3_sleep_time_choice"); wakeTime = sleepValue("sig3_wake_time_choice");
    if (!sleepSlot.matches("[1-6]") || !wakeSlot.matches("[1-6]")) throw new Exception("Choose both programs");
    if (!sleepTimeValid(sleepTime) || !sleepTimeValid(wakeTime) || sleepTime.equals(wakeTime))
        throw new Exception("Choose two different valid clock times");
    config = new JSONObject(); config.put("version", 1); config.put("programs", sleepPrograms());
    config.put("sleepSlot", sleepSlot); config.put("wakeSlot", wakeSlot);
    config.put("sleepTime", sleepTime); config.put("wakeTime", wakeTime);
    if (!prefs.edit().putString("configuration", config.toString()).commit())
        throw new Exception("Could not save sleep settings; previous settings retained");
} else if ("load".equals(mode)) {
    saved = prefs.getString("configuration", "");
    if (saved.length() == 0) {
        tasker.setVariable("SIG3_SleepEnabled", "0"); tasker.setVariable("SIG3_SleepActive", "0");
        tasker.setVariable("SIG3_SleepProgram", ""); tasker.setVariable("SIG3_WakeProgram", "");
        tasker.setVariable("SIG3_SleepTime", ""); tasker.setVariable("SIG3_WakeTime", "");
        tasker.setVariable("SIG3_SleepSettingsStatus", "Choose sleep and wake programs and times"); return "unconfigured";
    }
    config = new JSONObject(saved);
    if (config.getInt("version") != 1 || !config.getJSONArray("programs").toString().equals(sleepPrograms().toString())) {
        tasker.setVariable("SIG3_SleepEnabled", "0");
        tasker.setVariable("SIG3_SleepActive", "0");
        tasker.setVariable("SIG3_SleepProgram", ""); tasker.setVariable("SIG3_WakeProgram", "");
        tasker.setVariable("SIG3_SleepSettingsStatus", "Program mapping changed; choose sleep programs again");
        return "mapping-changed";
    }
    sleepSlot = config.getString("sleepSlot"); wakeSlot = config.getString("wakeSlot");
    sleepTime = config.getString("sleepTime"); wakeTime = config.getString("wakeTime");
    if (!sleepSlot.matches("[1-6]") || !wakeSlot.matches("[1-6]") || !sleepTimeValid(sleepTime)
        || !sleepTimeValid(wakeTime) || sleepTime.equals(wakeTime)) throw new Exception("Invalid saved sleep settings");
} else throw new Exception("Unknown sleep settings operation");
// Time contexts reevaluate immediately when their variables change.
if ("save".equals(mode) || !sleepTime.equals(sleepValue("SIG3_SleepTime"))
        || !wakeTime.equals(sleepValue("SIG3_WakeTime"))
        || !sleepSlot.equals(sleepValue("SIG3_SleepProgram"))
        || !wakeSlot.equals(sleepValue("SIG3_WakeProgram"))) {
    tasker.setVariable("SIG3_SleepEnabled", "0"); tasker.setVariable("SIG3_SleepActive", "0");
}
tasker.setVariable("SIG3_SleepProgram", sleepSlot); tasker.setVariable("SIG3_WakeProgram", wakeSlot);
// Do not reevaluate Time contexts when a scheduled event reloads unchanged settings.
if (!sleepTime.equals(sleepValue("SIG3_SleepTime"))) tasker.setVariable("SIG3_SleepTime", sleepTime);
if (!wakeTime.equals(sleepValue("SIG3_WakeTime"))) tasker.setVariable("SIG3_WakeTime", wakeTime);
tasker.setVariable("SIG3_SleepSettingsStatus", "Sleep " + sleepTime.replace('.', ':') + ": " + config.getJSONArray("programs").getString(Integer.parseInt(sleepSlot)-1)
    + "; wake " + wakeTime.replace('.', ':') + ": " + config.getJSONArray("programs").getString(Integer.parseInt(wakeSlot)-1));
return "sleep settings " + mode;

/* Select programs and clock times without changing the current hearing program. */
import android.app.Activity;
import android.app.AlertDialog;
import android.app.TimePickerDialog;
import android.content.DialogInterface;
import android.widget.*;
import android.view.View;
import android.os.Handler;
import android.os.Looper;
import java.util.function.Consumer;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

names = new String[7]; names[0] = "Choose a program";
for (i = 1; i <= 6; i++) {
    name = tasker.getVariable("SIG3_ProgramName" + i);
    if (name == null || name.trim().length() == 0 || name.startsWith("%"))
        throw new Exception("Configure all six program names before opening sleep settings");
    names[i] = name;
}
selected = new int[] {0, 0};
for (i = 0; i < 2; i++) {
    value = tasker.getVariable(i == 0 ? "SIG3_SleepProgram" : "SIG3_WakeProgram");
    if (value != null && value.matches("[1-6]")) selected[i] = Integer.parseInt(value);
}
times = new String[] {"22.00", "07.00"};
for (i = 0; i < 2; i++) {
    value = tasker.getVariable(i == 0 ? "SIG3_SleepTime" : "SIG3_WakeTime");
    if (value != null && value.matches("(?:[01][0-9]|2[0-3])\\.[0-5][0-9]")) times[i] = value;
}
decision = new AtomicReference("cancel"); activityRef = new AtomicReference(); dialogRef = new AtomicReference();
done = new CountDownLatch(1); ui = new Handler(Looper.getMainLooper());
tasker.setVariable("sig3_sleep_settings_decision", "cancel");
try {
    tasker.doWithActivity(new Consumer() {
        accept(Object value) {
            final Activity screen = (Activity) value; activityRef.set(screen);
            layout = new LinearLayout(screen); layout.setOrientation(LinearLayout.VERTICAL);
            padding = (int) (20 * screen.getResources().getDisplayMetrics().density);
            layout.setPadding(padding, padding, padding, padding);
            sleepLabel = new TextView(screen); sleepLabel.setText("Sleep program"); layout.addView(sleepLabel);
            sleepProgram = new Spinner(screen);
            sleepProgram.setAdapter(new ArrayAdapter(screen, android.R.layout.simple_spinner_dropdown_item, names));
            sleepProgram.setSelection(selected[0]); layout.addView(sleepProgram);
            sleepTime = new Button(screen); sleepTime.setText("Sleep time: " + times[0].replace('.', ':')); layout.addView(sleepTime);
            sleepTime.setOnClickListener(new View.OnClickListener() {
                onClick(View view) {
                    new TimePickerDialog(screen, new TimePickerDialog.OnTimeSetListener() {
                        onTimeSet(TimePicker picker, int hour, int minute) {
                            times[0] = String.format(java.util.Locale.US, "%02d.%02d", hour, minute);
                            sleepTime.setText("Sleep time: " + times[0].replace('.', ':'));
                        }
                    }, Integer.parseInt(times[0].substring(0, 2)), Integer.parseInt(times[0].substring(3)), true).show();
                }
            });
            wakeLabel = new TextView(screen); wakeLabel.setText("Wake program"); layout.addView(wakeLabel);
            wakeProgram = new Spinner(screen);
            wakeProgram.setAdapter(new ArrayAdapter(screen, android.R.layout.simple_spinner_dropdown_item, names));
            wakeProgram.setSelection(selected[1]); layout.addView(wakeProgram);
            wakeTime = new Button(screen); wakeTime.setText("Wake time: " + times[1].replace('.', ':')); layout.addView(wakeTime);
            wakeTime.setOnClickListener(new View.OnClickListener() {
                onClick(View view) {
                    new TimePickerDialog(screen, new TimePickerDialog.OnTimeSetListener() {
                        onTimeSet(TimePicker picker, int hour, int minute) {
                            times[1] = String.format(java.util.Locale.US, "%02d.%02d", hour, minute);
                            wakeTime.setText("Wake time: " + times[1].replace('.', ':'));
                        }
                    }, Integer.parseInt(times[1].substring(0, 2)), Integer.parseInt(times[1].substring(3)), true).show();
                }
            });
            note = new TextView(screen);
            note.setText("Times use the phone's local clock. Save turns the schedule off. Run SIG3_SleepEnable to enable it, or SIG3_SleepDisable to stop it. Switching requires Signia open and the phone unlocked.");
            layout.addView(note);
            dialog = new AlertDialog.Builder(screen).setTitle("HeySig3 sleep settings").setView(layout)
                .setPositiveButton("Save", null).setNegativeButton("Cancel", null).create();
            dialogRef.set(dialog); dialog.setCancelable(true);
            dialog.setOnDismissListener(new DialogInterface.OnDismissListener() {
                onDismiss(DialogInterface dialog) { done.countDown(); screen.finish(); }
            });
            dialog.show();
            dialog.getButton(DialogInterface.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener() {
                onClick(View view) {
                    if (sleepProgram.getSelectedItemPosition() == 0 || wakeProgram.getSelectedItemPosition() == 0) {
                        Toast.makeText(screen, "Choose both programs", Toast.LENGTH_SHORT).show(); return;
                    }
                    if (times[0].equals(times[1])) {
                        Toast.makeText(screen, "Choose different sleep and wake times", Toast.LENGTH_SHORT).show(); return;
                    }
                    selected[0] = sleepProgram.getSelectedItemPosition(); selected[1] = wakeProgram.getSelectedItemPosition();
                    decision.set("save"); dialog.dismiss();
                }
            });
        }
    });
    if (done.await(180, TimeUnit.SECONDS) && "save".equals(decision.get())) {
        tasker.setVariable("sig3_sleep_program_choice", "" + selected[0]);
        tasker.setVariable("sig3_wake_program_choice", "" + selected[1]);
        tasker.setVariable("sig3_sleep_time_choice", times[0]); tasker.setVariable("sig3_wake_time_choice", times[1]);
        tasker.setVariable("sig3_sleep_settings_decision", "save");
    }
} finally {
    ui.post(new Runnable() {
        run() {
            dialog = dialogRef.get(); if (dialog != null && dialog.isShowing()) dialog.dismiss();
            screen = activityRef.get(); if (screen != null && !screen.isFinishing()) screen.finish();
        }
    });
}
return tasker.getVariable("sig3_sleep_settings_decision");

